#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n\nimport argparse\nimport sys\nimport os\nfrom pathlib import Path\nfrom animations import show_welcome, show_loading, show_success, show_error, show_info\nfrom downloader import download_video, download_audio, detect_platform\n\ndef setup_download_folder():\n    \"\"\"ডাউনলোড ফোল্ডার তৈরি করুন\"\"\"\n    download_dir = Path.home() / 'Downloads' / 'SocialMediaDownloads'\n    download_dir.mkdir(parents=True, exist_ok=True)\n    return str(download_dir)\n\ndef main():\n    parser = argparse.ArgumentParser(\n        description='📱 সোশ্যাল মিডিয়া ভিডিও/অডিও ডাউনলোডার - CLI সংস্করণ',\n        formatter_class=argparse.RawDescriptionHelpFormatter,\n        epilog=\"\"\"\n📚 উদাহরণ:\n  ভিডিও ডাউনলোড:\n    python3 cli.py -u \"https://www.youtube.com/watch?v=...\" -t video\n    python3 cli.py --url \"https://www.tiktok.com/@.../video/...\" --type video\n  \n  অডিও ডাউনলোড:\n    python3 cli.py -u \"https://www.youtube.com/watch?v=...\" -t audio\n    python3 cli.py --url \"https://soundcloud.com/user/track\" --type audio\n\n  কাস্টম ফোল্ডার:\n    python3 cli.py -u \"URL\" -t video -o \"/path/to/folder\"\n        \"\"\"\n    )\n    \n    parser.add_argument(\n        '-u', '--url',\n        type=str,\n        required=True,\n        help='📺 ভিডিও বা অডিওর URL (উদাহরণ: YouTube, TikTok, Instagram ইত্যাদি)'\n    )\n    \n    parser.add_argument(\n        '-t', '--type',\n        type=str,\n        choices=['video', 'audio'],\n        required=True,\n        help='📥 ডাউনলোড টাইপ: video বা audio'\n    )\n    \n    parser.add_argument(\n        '-o', '--output',\n        type=str,\n        default=None,\n        help='💾 আউটপুট ফোল্ডার পাথ (ডিফল্ট: ~/Downloads/SocialMediaDownloads)'\n    )\n    \n    parser.add_argument(\n        '-v', '--version',\n        action='version',\n        version='%(prog)s 1.0.0'\n    )\n    \n    args = parser.parse_args()\n    \n    # URL ভ্যালিডেশন\n    if not args.url.startswith(('http://', 'https://')):\n        show_error(\"❌ সঠিক URL দিন (http:// বা https:// দিয়ে শুরু করুন)\")\n        sys.exit(1)\n    \n    # আউটপুট ফোল্ডার সেটআপ\n    if args.output:\n        output_folder = args.output\n        Path(output_folder).mkdir(parents=True, exist_ok=True)\n    else:\n        output_folder = setup_download_folder()\n    \n    # প্ল্যাটফর্ম ডিটেক্ট করুন\n    platform = detect_platform(args.url)\n    show_info(f\"🔍 প্ল্যাটফর্ম শনাক্ত করা হয়েছে: {platform.upper()}\")\n    \n    # ডাউনলোড শুরু করুন\n    if args.type == 'video':\n        show_loading(\"🎥 ভিডিও ডাউনলোড শুরু হচ্ছে\", 2)\n        download_video(args.url, output_folder)\n    elif args.type == 'audio':\n        show_loading(\"🎵 অডিও ডাউনলোড শুরু হচ্ছে\", 2)\n        download_audio(args.url, output_folder)\n    \n    show_info(f\"✅ ফাইল এখানে সংরক্ষিত হয়েছে: {output_folder}\")\n\nif __name__ == \"__main__\":\n    try:\n        main()\n    except KeyboardInterrupt:\n        show_error(\"\\n\\n❌ প্রোগ্রাম বন্ধ করা হয়েছে (Ctrl+C)\")\n        sys.exit(0)\n    except Exception as e:\n        show_error(f\"\\n❌ একটি ত্রুটি ঘটেছে: {str(e)}\")\n        sys.exit(1)\n